package migration

import (
	"testing"

	"github.com/nimi-io/better-auth-go/adapter/sqladapter/dialect"
)

// The SQL Server ALTER TABLE path cannot be generated by the fixture script (it needs an
// existing table); these expectations follow Kysely's MssqlQueryCompiler (no "column"
// keyword after "add") and getMigrations' filtered unique index for nullable columns.
func TestCompileSQLServerAlterPath(t *testing.T) {
	c := compiler{d: dialect.MSSQL}
	if got, want := c.addColumn("user", column{name: "code", dataType: "varchar(255)"}), `alter table "user" add "code" varchar(255)`; got != want {
		t.Fatalf("got %s", got)
	}
	if got, want := c.createIndex("user_code_uidx", "user", []string{"code"}, true, "code"), `create unique index "user_code_uidx" on "user" ("code") where "code" is not null`; got != want {
		t.Fatalf("got %s", got)
	}
}

func TestCompileLiterals(t *testing.T) {
	for _, c := range []struct {
		d    dialect.Dialect
		v    any
		want string
	}{
		{dialect.Postgres, "it's", `'it''s'`},
		{dialect.MySQL, `back\slash 'q'`, `'back\\slash ''q'''`},
		{dialect.SQLite, `back\slash`, `'back\slash'`},
		{dialect.Postgres, true, "true"},
		{dialect.Postgres, 10, "10"},
		{dialect.Postgres, int64(-3), "-3"},
		{dialect.Postgres, 1.5, "1.5"},
		{dialect.Postgres, 1e21, "1e+21"},
		{dialect.Postgres, 1.5e-7, "1.5e-7"},
		{dialect.Postgres, 0.000001, "0.000001"},
		{dialect.Postgres, 123456789012.0, "123456789012"},
	} {
		got, err := compiler{d: c.d}.immediate(c.v)
		if err != nil || got != c.want {
			t.Errorf("%s %v: got %q, %v; want %q", c.d, c.v, got, err, c.want)
		}
	}
}

func TestCompileIdentifiers(t *testing.T) {
	if got := (compiler{d: dialect.MySQL}).table("we`ird"); got != "`we``ird`" {
		t.Fatalf("got %s", got)
	}
	if got := (compiler{d: dialect.Postgres, schema: "auth"}).table(`we"ird`); got != `"auth"."we""ird"` {
		t.Fatalf("got %s", got)
	}
	// Kysely's parseTable splits a dotted name into schema and table.
	if got := (compiler{d: dialect.Postgres, schema: "auth"}).table("internal.users"); got != `"internal"."users"` {
		t.Fatalf("got %s", got)
	}
}
